param([Parameter(Mandatory=$true)][string]$OutputDirectory,[Parameter(Mandatory=$true)][string]$ResearchDirectory)
$ErrorActionPreference='Stop';if($PSVersionTable.PSVersion.Major -lt 7){throw 'Use pwsh.exe'}
$mwCFRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$mwCFOut=[IO.Path]::GetFullPath($OutputDirectory);$mwCFResearch=(Resolve-Path -LiteralPath $ResearchDirectory).Path;$mwCFAllowed=Join-Path $mwCFRoot 'reports/m4-crt-control'
if(-not $mwCFOut.StartsWith($mwCFAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase) -or -not $mwCFResearch.StartsWith($mwCFAllowed+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Private control evidence required'}
$mwCFName=Split-Path $mwCFOut -Leaf;if($mwCFName -notmatch '^[a-z][a-z0-9-]{0,63}$' -or $mwCFName -match '^(con|prn|aux|nul|com[0-9]|lpt[0-9])$'){throw 'Fresh simple control experiment name'}
$mwCFBuild=Join-Path $mwCFRoot "build/m4-crt-control-$mwCFName";if((Test-Path -LiteralPath $mwCFOut) -or (Test-Path -LiteralPath $mwCFBuild)){throw 'Fresh original control report/build required'}
function Get-MWCFHash([string]$Path){(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
$mwCFProvider=Join-Path $mwCFRoot 'local/mw3-staged/Shared_DLLs/MSVCRT.DLL';if((Get-MWCFHash $mwCFProvider) -ne '2d5670881a6d13a100e37da297f6eeb876f68b63073a28eb5d650625c60f9bf7'){throw 'Exact provider identity required'}
$mwCFSources=[ordered]@{};foreach($mwCFFile in @(Get-ChildItem -LiteralPath $PSScriptRoot -File;Get-Item -LiteralPath (Join-Path $PSScriptRoot '../m4-crt/probe_common.hpp'),(Join-Path $PSScriptRoot '../m4-crt/probe_io.hpp'),(Join-Path $mwCFResearch 'probe_spec.hpp'))|Sort-Object FullName){$mwCFSources[$mwCFFile.FullName]=Get-MWCFHash $mwCFFile.FullName}
New-Item -ItemType Directory $mwCFOut|Out-Null;$mwCFCopies=[Collections.Generic.List[object]]::new();foreach($mwCFPath in $mwCFSources.Keys){$mwCFCopy=Join-Path (Join-Path $mwCFOut 'sources') ([IO.Path]::GetRelativePath($mwCFRoot,$mwCFPath));New-Item -ItemType Directory -Force -Path (Split-Path $mwCFCopy)|Out-Null;Copy-Item -LiteralPath $mwCFPath -Destination $mwCFCopy;if((Get-MWCFHash $mwCFCopy) -ne $mwCFSources[$mwCFPath]){throw 'Exact literal original control source preservation'};$mwCFCopies.Add([ordered]@{original_path=$mwCFPath;preserved_path=$mwCFCopy;sha256=$mwCFSources[$mwCFPath]})}
$mwCFCommands=[Collections.Generic.List[object]]::new()
function Invoke-MWCF([string]$Program,[string[]]$Arguments,[string]$Log){$mwCFSaved=$ErrorActionPreference;$ErrorActionPreference='Continue';try{& $Program @Arguments 2>&1|Tee-Object -FilePath $Log;$mwCFExit=$LASTEXITCODE}finally{$ErrorActionPreference=$mwCFSaved};$mwCFCommands.Add([ordered]@{program=$Program;arguments=$Arguments;exit_code=$mwCFExit;log_path=$Log;log_sha256=(Get-MWCFHash $Log)});if($mwCFExit -ne 0){throw "Original control tool failed $Program exit=$mwCFExit"}}
$mwCFVS='C:/Program Files/Microsoft Visual Studio/18/Community';$mwCFPassed=$false;$mwCFFailure=$null
try{
 Import-Module (Join-Path $mwCFVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll');Enter-VsDevShell -VsInstallPath $mwCFVS -SkipAutomaticLocation -DevCmdArguments '-arch=x86 -host_arch=x64'|Out-Null
 $mwCFCMake=Join-Path $mwCFVS 'Common7/IDE/CommonExtensions/Microsoft/CMake/CMake/bin/cmake.exe'
 Invoke-MWCF $mwCFCMake @('-S',$PSScriptRoot,'-B',$mwCFBuild,'-G','Visual Studio 18 2026','-A','Win32',"-DMW34_CONTROL_INCLUDE=$mwCFResearch") (Join-Path $mwCFOut 'configure.log')
 Invoke-MWCF $mwCFCMake @('--build',$mwCFBuild,'--config','Release','--verbose') (Join-Path $mwCFOut 'build.log')
 $mwCFWorker=Join-Path $mwCFBuild 'Release/mw34_control_reference.exe';Invoke-MWCF $mwCFWorker @('--check-hash') (Join-Path $mwCFOut 'hash.log');foreach($mwCFPath in $mwCFSources.Keys){if((Get-MWCFHash $mwCFPath) -ne $mwCFSources[$mwCFPath]){throw 'Original control source changed during build'}};$mwCFPassed=$true
}catch{$mwCFFailure=$_.Exception.Message;$_|Out-String|Set-Content -LiteralPath (Join-Path $mwCFOut 'failure.txt');throw}finally{
 $mwCFArtifacts=[ordered]@{};foreach($mwCFFile in @(Get-ChildItem -LiteralPath $mwCFOut -File -Recurse;Get-ChildItem -LiteralPath $mwCFResearch -File -Recurse;if(Test-Path -LiteralPath $mwCFBuild){Get-ChildItem -LiteralPath $mwCFBuild -File -Recurse|Where-Object {$_.Extension -in @('.exe','.obj','.lib','.txt','.cmake','.vcxproj','.props','.json','.tlog')}})|Sort-Object FullName){$mwCFArtifacts[$mwCFFile.FullName]=Get-MWCFHash $mwCFFile.FullName}
 $mwCFTools=[ordered]@{};foreach($mwCFTool in @($mwCFCMake,(Get-Process -Id $PID).Path,(Join-Path $mwCFVS 'Common7/Tools/Microsoft.VisualStudio.DevShell.dll'),(Join-Path $mwCFVS 'MSBuild/Current/Bin/amd64/MSBuild.exe'))+@('cl.exe','link.exe','rc.exe','ml.exe'|ForEach-Object {(Get-Command $_ -ErrorAction SilentlyContinue).Source})){if($mwCFTool -and (Test-Path -LiteralPath $mwCFTool)){$mwCFTools[$mwCFTool]=Get-MWCFHash $mwCFTool}}
 [ordered]@{passed=$mwCFPassed;failure=$mwCFFailure;scope='Original exact control provider worker only; native equivalence pending';source_files=$mwCFSources;literal_source_copies=@($mwCFCopies);tool_files=$mwCFTools;artifacts=$mwCFArtifacts;commands=@($mwCFCommands);worker=$mwCFWorker;provider_path=$mwCFProvider;provider_sha256=(Get-MWCFHash $mwCFProvider);pack_path=(Join-Path $mwCFResearch 'pack.bin');pack_sha256=(Get-MWCFHash (Join-Path $mwCFResearch 'pack.bin'));whole_M4_complete=$false}|ConvertTo-Json -Depth 16|Set-Content -Encoding utf8 -LiteralPath (Join-Path $mwCFOut 'build.json')
}
